<?php else: ?><section class="panel"><h2>خلاصه ارسال</h2><p>شهید: <b><?= e(Namira\CallMartyrFields::label($db,$batch['data']['martyr'])) ?></b></p><p>تعداد آثار: <?= fa(count($works)) ?></p><p class="hint">ذخیره پیش‌نویس با ثبت نهایی متفاوت است. تنها اثر ثبت نهایی موفق، کد رهگیری دریافت می‌کند.</p></section>
<?php $receipt=$_SESSION['call_receipts'][$batchId]??null;if($receipt): ?><div class="notice" role="status"><b>نتیجه آخرین ثبت</b><ul><?php foreach($receipt['works'] as $workId=>$r): ?><li>اثر #<?= fa($workId) ?>: <?php if($r['ok']): ?>کد <b dir="ltr"><?= e($r['tracking']) ?></b><?php else: ?><?= e(implode('، ',$r['errors'])) ?> · <a href="<?= e(url('submit-art',['call_id'=>$call['id'],'batch'=>$batchId,'step'=>2,'work'=>$workId])) ?>">تکمیل این اثر</a><?php endif ?></li><?php endforeach ?></ul></div><?php endif ?>
<form method="post" class="panel" data-call-form="finalize"><?= CallUI::csrfForm('call2-finalize',['batch_id'=>$batchId,'call_id'=>$call['id'],'rules_version'=>$call['rules_version']]) ?><div class="call-review-list"><?php foreach($works as $work): ?><article><label class="call-check"><input type="checkbox" name="work_ids[]" value="<?= $work['id'] ?>" <?= $work['review_state']==='draft'?'checked':'' ?>><b><?= e($work['title']?:'اثر بدون عنوان') ?></b></label><p><?= e(CallEntries::statusLabel($work['review_state'])) ?> · انتشار: <?= e(CallUI::publicState($work['publication_state'])) ?></p><?php if($work['tracking']): ?><p>کد رهگیری: <b dir="ltr"><?= e($work['tracking']) ?></b></p><?php endif ?><p><?= e(CallEntries::section($batch,(int)$work['section_id'])['title']) ?> · <?= fa(count($work['files'])) ?> فایل · صاحب اثر: <?= e($work['owner_mode']==='unknown'?'نامشخص':($work['owner']['name']??'')) ?></p><?php if($work['data']['text']!==''): ?><details><summary>متن اثر</summary><p class="prose"><?= e($work['data']['text']) ?></p></details><?php endif ?><a href="<?= e(url('submit-art',['call_id'=>$call['id'],'batch'=>$batchId,'step'=>2,'work'=>$work['id']])) ?>">مشاهده و ویرایش این اثر</a><div data-call-result-for="<?= $work['id'] ?>"></div></article><?php endforeach ?></div>
<details><summary>قوانین این فراخوان؛ نسخه فعلی</summary><div class="prose"><?= e($call['rules_text']) ?></div></details><label class="call-check"><input type="checkbox" name="accept_rules" value="1">قوانین نمایش و دانلود رایگان با حفظ انتساب را می‌پذیرم و اجازه لازم برای ارسال اثر را دارم.</label><p class="hint">این پذیرش به معنی انتقال مالکیت اثر نیست؛ صاحب اثر نامشخص نیز باید همین قوانین را بپذیرد.</p><div data-call-form-errors role="alert"></div><button class="primary">ثبت نهایی آثار انتخاب‌شده</button></form><?php endif ?></div>